def solve(input_string):
    """
    This function takes a string as input and returns the number of unique characters 
    in the string, ignoring case.
    """
    input_str = input_string.lower()
    unique_chars = set()
    for char in input_str:
        if char.isalpha():
            unique_chars.add(char)
    return len(unique_chars)
